#' @title Compute spatial clusters
#'
#' @description
#' Performs spatial clustering of inferred chromosome arm
#' log ratio profiles using the BANKSY algorithm.
#'
#' The resulting clusters represent spatially organised
#' groups of cells with similar somatic copy number
#' aberration profiles.
#'
#' @param arm_ratios Matrix of chromosome arm log ratio
#' values generated by compute_arm_ratios()
#' @param xenium.obj Normalised Xenium object
#' @param lambda BANKSY spatial weight parameter
#' @param k_geom Number of spatial neighbours used by
#' BANKSY.
#' @param dims Principal components used by
#' Seurat::FindNeighbors()
#' @param k_param Number of neighbours used by
#' Seurat::FindNeighbors()
#' @param resolution Resolution parameter used by
#' Seurat::FindClusters()
#' @param seed Random seed used by
#' Seurat::FindClusters()
#'
#' @returns A Seurat object containing BANKSY-derived
#' spatial clusters.
#'
#' @references
#' Singhal, V., Chou, N., Lee, J. et al.
#' BANKSY unifies cell typing and tissue domain segmentation
#' for scalable spatial omics data analysis.
#' Nature Genetics 56, 431-441 (2024).
#' \doi{10.1038/s41588-024-01664-3}
#'
#' @examples
#' \dontrun{
#' # Spatial clustering using lambda = 0.8, resolution = 0.1
#' BANKSY.obj <- compute_spatial_clusters(
#'    arm_ratios = arm_ratios,
#'    xenium.obj = xenium.obj,
#'   lambda = 0.8,
#'   resolution = c(0.1))}
#'
#' @export
compute_spatial_clusters <- function(
    arm_ratios,
    xenium.obj,
    lambda = 0.8,
    k_geom = 30,
    dims = 1:8,
    k_param = 30,
    resolution = 0.1,
    seed = 1
) {
  if (!all(colnames(arm_ratios) %in% colnames(xenium.obj))) {

    stop(
      "Cell names in arm_ratios do not match xenium.obj"
    )

  }

  # Create Seurat object with arm_ratios per cell data
  BANKSY.obj <- Seurat::CreateSeuratObject(
    counts = arm_ratios,
    data = arm_ratios,
    assay = "arms"
  )

  # Create scale data slot without actually scaling
  BANKSY.obj <- Seurat::ScaleData(
    BANKSY.obj,
    assay = "arms",
    do.center = FALSE,
    do.scale = FALSE,
    verbose = FALSE
  )

  # Add xenium image to Banksy object
  BANKSY.obj@images <- xenium.obj@images

  # Set chromosome arms as variable features for Banksy
  Seurat::VariableFeatures(BANKSY.obj) <-
    rownames(BANKSY.obj[["arms"]])

  BANKSY.obj <- run_banksy_internal(
    BANKSY.obj,
    lambda = lambda,
    assay = "arms",
    slot = "data",
    features = Seurat::VariableFeatures(BANKSY.obj),
    k_geom = k_geom
  )

  Seurat::DefaultAssay(BANKSY.obj) <- "BANKSY"

  Seurat::VariableFeatures(BANKSY.obj) <-
    rownames(BANKSY.obj[["BANKSY"]])

  BANKSY.obj <- Seurat::RunPCA(
    BANKSY.obj,
    assay = "BANKSY",
    reduction.name = "pca.banksy"
  )

  BANKSY.obj <- Seurat::FindNeighbors(
    BANKSY.obj,
    reduction = "pca.banksy",
    dims = dims,
    k.param = k_param
  )

  BANKSY.obj <- Seurat::FindClusters(
    BANKSY.obj,
    resolution = resolution,
    algorithm = 4,
    random.seed = seed
  )

  return(BANKSY.obj)
}
